"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["93596"],{13701(e){e.exports=JSON.parse('{"id":"V4-212","slug":"banking-as-a-service","term":"Banking-as-a-Service","also_known_as":[],"difficulty":"Advanced","definition":"Banking-as-a-Service (BaaS) is a model in which licensed banks provide their banking infrastructure and services, such as accounts, payments and cards, to non-bank companies through application programming interfaces, allowing those companies to offer financial products under their own brand.","explanation":["Becoming a licensed bank is costly and slow. Banking-as-a-Service allows fintech companies, retailers, technology platforms and other businesses to offer financial services by partnering with a licensed bank, which holds customer deposits and handles regulatory requirements.","A typical arrangement involves three parties: the licensed bank, which provides the regulated services; often a technology provider, sometimes called a middleware platform, which connects the bank\u2019s systems to other businesses; and the brand that serves customers.","For example, a ride-hailing app might offer its drivers a debit card and account, with the actual accounts held at a partner bank through a BaaS provider.","BaaS has supported the growth of embedded finance, in which financial services are built into non-financial products and apps.","However, BaaS has faced problems. US regulators have taken action against several partner banks for weaknesses in anti-money laundering controls and oversight of fintech partners. The 2024 bankruptcy of the BaaS middleware company Synapse left many customers temporarily unable to access their money, because records of who owned which funds were unclear. These events have led to greater scrutiny of the model."],"note":"","total":1725,"prev":{"slug":"bank-transfer","term":"Bank Transfer"},"next":{"slug":"bankruptcy","term":"Bankruptcy"}}')}}]);